// AllGoldenVectors returns all golden vectors for contract testing.
func AllGoldenVectors() []GoldenVectorSpec {
	copied := make([]GoldenVectorSpec, len(canonicalGoldenVectors))
	copy(copied, canonicalGoldenVectors)
	return copied
}

// LookupGoldenVector retrieves a golden vector specification by ID.
func LookupGoldenVector(vectorID string) (GoldenVectorSpec, bool) {
	for _, v := range canonicalGoldenVectors {
		if v.VectorID == vectorID {
			return v, true
		}
	}
	return GoldenVectorSpec{}, false
}
